// @exec: {"yield_time_ms": 120000, "max_output_tokens": 900}
const prompts=[
["opening","生成一张用于白底长文章中穿插的横向黑底解释图，16:9。核心参考为附件图片，延续黑底、浅蓝用户文字、淡绿色说明文字、灰色层叠模型的数学动画视觉。所有可见文字只有简体中文，不出现英文字母或代码，不用任何标题栏、页码、水印、图注、仪表盘或卡片列表。极简画面：左上浅蓝色角色标签“用户：”，其下白色宋体文字分两行“读取会议纪要，”“整理确定事项与待确认问题。” 中间偏左画一张细白边框的文件纸，标签“会议纪要”，纸面正文仅三行“试点周一开始”“预算待审批”“负责人待确认”。纸保持在画面最左下角与模型隔开。画面右侧灰色平行板层叠的大语言模型，正面只写“大语言模型”。从用户消息到模型的唯一白箭头，箭头下浅蓝小字“当前需求”；文件纸与模型之间留黑色空白，无箭头。用户文字与模型之间还可以一行白字“文件位置：会议纪要”。文件纸旁黄色短标签“正文尚未提供”。字号大，留白充足，参考附件图形而不是抄写英文。"],
["tool","生成一张用于白底长文章中穿插的横向黑底解释图，16:9。参考附件纯黑背景、淡绿说明文字、浅蓝用户信息、白箭头、少量黄色焦点、宋体中文的数学动画语言。所有可见文字只有简体中文，无英文字母、代码、水印、标题栏或页码。主题是工具定义如何指导生成调用请求。左半边一个淡绿色细线矩形，内部有三段文字：小标题“工具定义”；“名称：读取文件”；“用途：取得文本正文”；“参数规则：必须提供文件路径”。右半边一个浅蓝色细线矩形，内部小标题“本次请求”；“工具：读取文件”；“文件路径：会议纪要”。左框到右框有一根清晰白箭头，箭头上方短字“依据定义填写”。右框下黄色短句“请求已生成，文件尚未读取”。左框和右框都很宽，文字四周有足够空白，不画软件界面，不画复杂网络。上下留黑色呼吸空间，正文文字比常规课件大。"],
["loop","生成一张横向16:9纯黑底中文解释图，插在白底长文章中。延续附件灰色层叠模型、浅蓝文字、淡绿文字、白色细箭头与宋体。所有文字必须简体中文，无英文、代码、标题栏、页码、水印。画面是清晰两行顺序流程，不是复杂循环交叉图。上行从左到右：浅蓝文字组“用户需求”“文件路径”“工具定义”，白箭头指向中间灰色层叠板正面“大语言模型”，模型上方“第一次调用”；再白箭头到右上黄色细线框“读取请求”。从右上读取请求垂直向下白箭头，到右下白色细线框“执行程序”，框内小字“读取会议纪要”。下行从右往左：执行程序向左白箭头，箭头上方绿色标签“返回正文”，进入中下方另一个相同灰色层叠板“大语言模型”，模型下方“第二次调用”；该模型向左白箭头到左下淡绿色答案文字“确定：试点周一开始”“待确认：预算、负责人”。必须精确这个方向：左上→中上→右上→右下→中下→左下，五根箭头都清楚。每个模型上行下行都小巧不占满画面，所有中文保持可读，绿色用于结果。"]
];
store("newprompts",prompts);
await Promise.all(prompts.map(async([key,prompt])=>{const r=await tools.image_gen__imagegen({referenced_image_paths:load("refs"),prompt});store(key,r);text({key,output_hint:r.output_hint});generatedImage(r);}));

// @exec: {"yield_time_ms": 120000, "max_output_tokens": 500}
const r=await tools.image_gen__imagegen({referenced_image_paths:["/Users/w/code/For-Use-AI/Course/LLM_简要说明/素材/工程素材/images/append.jpg"],prompt:"Create a purely graphical, entirely wordless explanatory animation storyboard. One high resolution wide image with THREE equally sized panels arranged horizontally separated by generous black gutters. Absolutely NO text, letters, numbers, titles, code, captions, labels, pseudo-text, watermarks anywhere. Reference attached image only for pure black background, crisp mathematical vector geometry, muted pastel blue and green, white outlines, and a gray perspective stack representing a language model. Not a slide deck, not cards containing writing. Show THREE consecutive states of THE SAME scene about external file information being read into context, with identical camera and object positions throughout. In EVERY panel: a large folded-corner document outline at far left contains three clearly distinct graphical shapes vertically: cyan circle, green triangle, amber square. Center-left below it, a small thin gray gear icon represents the reading program. At center is a white outlined open horizontal tray representing current model input, and at far right a miniature layered gray slab model like the reference, WITHOUT any lettering. Panel ONE: original document contains all three shapes. Input tray holds only a tiny outline thumbnail of the folded-corner document, NO content shapes in the tray. Reader gear idle. Panel TWO: original document still contains exactly all three shapes, gear linked to the document with a thin white line. Show a COPY of each of the three shapes (cyan circle, green triangle, amber square) traveling in a short curved thin white arrow from the document through the gear toward the input tray, with the same tiny document thumbnail remaining inside tray. Original shapes must remain in original document: reading is copying, never consuming. Panel THREE: original document unchanged at left, gear idle. Tray now contains document thumbnail PLUS all three colored copied shapes, neatly separated. A single white arrow connects this enriched tray to model on right. Consistent object identity, matching colors and silhouettes across panels, large simple geometry, flat/vector-like with subtle perspective only on gray model. No decorative particles or neural webs. This should look like actual states of a Manim mechanism animation, not a wordless infographic of random symbols."});
store("nontext",r);text({output_hint:r.output_hint});generatedImage(r);

// @exec: {"yield_time_ms": 120000, "max_output_tokens": 600}
const jobs=[
["assemble","Create a wordless explanatory animation storyboard with THREE horizontal equal panels on pure black, thin subtle vertical dividers, large simple shapes and lots of negative space. No text, letters, numbers, captions, labels, code or watermarks anywhere. Match attached reference's Manim vector aesthetic, pastel green and cyan and gray layered slab model but remove all lettering. All panels identical geometry and object positions. Model is a small gray perspective slab stack at far right, and immediately left of it a long shallow white outlined tray. On far left four distinct sources vertically arranged: a cyan speech bubble containing three short cyan geometric bars; a green sheet with a gear-shaped seal and two green geometric bars representing system instructions; a gray stack of previous speech bubbles containing gray bars; a gold simple wrench outline with a small outlined rectangular connector. Panel ONE: all four sources on left and only three cyan bars inside tray: user request alone. Panel TWO: sources remain, copies of green bars, two gray bars and gold connector are halfway moving toward tray on three distinct short thin curves; cyan bars stay in tray. Panel THREE: originals stay, tray now holds grouped cyan bars, grouped green bars, grouped gray bars and gold connector, visibly separated and never blended; one white arrow from tray to layered model. The bars are geometric data fragments not writing. NO neural network webs, no holographic glow, no gradients. Depict accumulation from different sources without implying model weights are modified. Important design: reference gray model stays unchanged across panels, same size and position. This is an explanatory figure for an article, not slides."],
["execute","A purely wordless 3-panel horizontal storyboard showing request generation, external execution, return of data. Pure black background, pastel cyan green gold accents, white thin directional paths, flat Manim mathematical geometry with gray layered slab model matching attached reference. NO letters, writing, numerals, titles, captions, logos, watermarks, pseudo-text. Same camera and same object positions in all three panels. Model gray slabs on left; a large white thin-outlined gear on right; below gear sits a folded-corner document containing cyan circle, green triangle, gold square; bottom-left beside model a shallow white outlined tray. PANEL ONE: top-center between model and gear a gold outlined small rectangular ticket with a folded-corner file thumbnail inside, moving on white arrow from model toward gear. Gear idle and file untouched. Tray empty. PANEL TWO: identical ticket now inserted in a small rectangular socket on gear's left, fitting exactly; gear rotated modestly indicated by one short white curved arrow; a white connection from gear reaches file. Original document still holds all three shapes. Three copies of these shapes just emerge from document. PANEL THREE: file unchanged, gear idle. Copies of cyan circle green triangle gold square sit in tray beside model. A white U-shaped return path goes from gear down then left to tray, with arrowhead toward tray. One short white arrow then goes from tray to model, showing a new input. The outgoing request is gold ticket; returned information is three colored shapes: visually DIFFERENT. No other stray symbols or big arrows. Keep geometry elegant and uncluttered, clearly sequential, a scientific pedagogical diagram not a business infographic."]
];
store("nontextprompts",jobs);
await Promise.all(jobs.map(async([key,prompt])=>{const r=await tools.image_gen__imagegen({referenced_image_paths:["/Users/w/code/For-Use-AI/Course/LLM_简要说明/素材/工程素材/images/append.jpg"],prompt});store(key,r);text({key,output_hint:r.output_hint});generatedImage(r);}));

// @exec: {"yield_time_ms": 120000, "max_output_tokens": 1000}
const d=await tools.exec_command({cmd:"cat Course/AI的输入与输出/计划/二十镜头与生图提示词.md","max_output_tokens":16000});
const s=d.output; store("cnPrompts",s);
const prompt=s.slice(s.indexOf("## 通用提示词"),s.indexOf("## 固定对象"))+"\n"+s.slice(s.indexOf("## 镜头01｜"),s.indexOf("## 镜头02｜"))+"\n只生成镜头一，参考图只用其黑底与简洁科普视觉，不复制参考图英文与模型。精确三列三行，中文采用清晰简体黑体。";
const r=await tools.image_gen__imagegen({referenced_image_paths:["/Users/w/code/For-Use-AI/Course/LLM_简要说明/素材/工程素材/images/append.jpg"],prompt});text({output_hint:r.output_hint});generatedImage(r);

// @exec: {"yield_time_ms": 120000, "max_output_tokens": 1000}
const s=load("cnPrompts");
const prompt=s.slice(s.indexOf("## 通用提示词"),s.indexOf("## 固定对象"))+"\n"+s.slice(s.indexOf("## 镜头02｜"),s.indexOf("## 镜头03｜"))+"\n只生成镜头二。第二参考图是镜头一，用其最后一格作为起点。保证各格所有中文准确且大而清晰，模型参考第一图灰色层叠板但彻底去掉英文。最后三格气泡内原需求两行仍完整可读，外部副本只有一块标注用户需求的蓝色圆角块。绝不把完整需求缩写成无字蓝条，不把文件移入盘内。不要把旁白写在画面上。";
const r=await tools.image_gen__imagegen({referenced_image_paths:["/Users/w/code/For-Use-AI/Course/LLM_简要说明/素材/工程素材/images/append.jpg","/Users/w/.codex/generated_images/01a0a41b-40fc-7620-a4cc-d037fd5f98f4/exec-9410c247-0ac6-47f5-b422-6b1769d2c69c.png"],prompt});text({output_hint:r.output_hint});generatedImage(r);

// @exec: {"yield_time_ms": 120000, "max_output_tokens": 1000}
store("boardCommon","生成一张三列三行九格连续动画分镜板，整图横向16:9，每格16:9，细灰线分隔。各格从左至右逐行演进，同一场景通过局部放大解释机制，不是九张主题海报。纯黑背景，灰色透视层叠板代表语言模型，青蓝代表用户需求，绿色代表系统提示词，金色代表工具定义及请求，白色代表文件及执行程序。只用清晰简体中文短句，字号足够大，具体内容精确，不出现英文、编号、代码、水印。左上整板窄边角标注“教学示例”。对象线条精确、克制留白，不用人物、霓虹、装饰网络；图形的复制、对应、边界与路径承担解释。所有原始信息复制后仍保留。每格都增加有意义的理解，不用单纯淡入凑格子。参考图只参考黑底及灰色透视模型的视觉，不复制其英文或概率表。");
store("boardPrompts",[
"镜头一：一句需求之外，系统提示词如何加入。第一格蓝色用户气泡写“读取纪要，区分确定与待确认事项”，下有闭合会议纪要文件。第二格镜头拉远，气泡左侧的应用界面后方揭露绿色指令页，右侧为灰色模型，模型下标“语言模型”。第三格放大绿色指令页，标题“系统提示词”，内容两条“用中文回答”“保留不确定性”，页的上方明确来源“应用提供”。第四格用两条短连线，把“用中文回答”连向示意中文回答文字，把“保留不确定性”连向一个琥珀虚线框内的“待确认”，说明规则作用，尚无实际答案。第五格回到全景，中央出现薄白框“本轮输入”，蓝色需求副本已经在框内，外部原气泡仍在。第六格绿色系统指令副本移到框内，与蓝色需求保持不同分组，外部原绿色页保留。第七格局部放大框内，让“系统提示词：用中文回答；保留不确定性”和“用户需求：读取纪要，区分确定与待确认事项”两组清楚可读，不混成一条用户消息。第八格缩回全景，框内两组一起通过单一箭头指向语言模型，文件仍在输入框外。第九格稳定全景，绿色规则和蓝色需求在输入框内，模型外形未变；底部仅短句“组织输入，不改参数”。不要把绿色指令画成更新模型权重，不画答案生成。总共九格，突出界面之外的来源、规则的具体内容、不同来源分组进入输入这三个拆解层次。",
"镜头二：工具定义怎样展开。第一格本轮输入里已有绿色系统提示词与蓝色用户需求，新增金色折叠接口页“读取文件”，模型在右侧低亮。第二格放大接口页，展开三个分区“用途”“必填参数”“返回结果”。第三格突出用途区“取得文件正文”，旁边闭合文件向展开纸页的图形对应，标注“用途示意”，不是执行。第四格突出必填参数区“文件位置”，画一个空心槽，旁边放置一个小路径条“资料／会议纪要”。第五格路径条放入参数槽，两端对齐，标题“填写示例”，原始工具定义仍在背景。第六格突出返回结果区“文件内容”，其旁画空的正文轮廓并标注“返回类型”，绝对不要画实际纪要内容，尚未读取。第七格把三部分缩回同一金色工具定义页，清晰文字“读取文件”“用途：取得正文”“必填：文件位置”“返回：文件内容”。第八格全景，工具定义副本与系统提示词、用户需求共同留在本轮输入内，外部工具目录原件保留；框外白齿轮标注“执行程序”，静止且未收到请求。第九格对照构图，左侧工具定义在输入内，右侧执行程序在模型外，两者间无执行箭头，短句“说明怎样请求，尚未执行”。三列三行九格，同一金色页连续展开与收起，内容不是长段文字。",
"镜头三：模型输出的是调用请求。第一格左侧本轮输入包含系统提示词、需求、读取文件定义与位置“资料／会议纪要”，右侧语言模型，外部闭合文件仍在下方。第二格放大输入中的文件位置标记“资料／会议纪要”，旁边正文槽空白，短标签“只有位置”。第三格外部文件局部向观众展开三条内容“试点周一开始”“预算待审批”“负责人待确认”，与输入边界隔开，短标签“正文仍在外部”，这是给观众的对照，未发送给模型。第四格回全景，已有输入指向模型，文件原文依然在外部，模型右侧输出端出现空金色请求页。第五格请求页放大，标题“调用请求”，第一项出现“工具：读取文件”。第六格请求页增加第二项“文件位置：资料／会议纪要”。第七格左边工具定义的“必填：文件位置”与右边请求中的具体位置用一条短线对齐，清晰说明定义与填写值的对应，不增加正文。第八格缩回模型右方，请求页沿箭头送向白色执行程序，模型与执行程序有明确间隔，原输入仍在左侧。第九格请求页到达执行程序入口，外部文件还未打开；短句“模型提出请求，程序负责执行”。不画模型伸手读取，不提前返回文件内容。所有具体字词保持一致。",
"镜头四：执行结果怎样回到下一次输入。第一格全景左侧本轮输入，中间灰色语言模型，右侧白齿轮执行程序，下方外部会议纪要；金色调用请求已到程序入口，内容“读取文件”“资料／会议纪要”。第二格局部放大程序入口，对请求中的文件位置与外部文件位置画匹配短线，原始输入不动。第三格程序向外部文件建立单向读取路径，文件打开，露出三条内容“试点周一开始”“预算待审批”“负责人待确认”。第四格三条内容从原文件复制成一份白色结果页，原文件中的三条完整保留，结果标题“工具结果”。第五格工具结果通过返回路径交给应用侧的输入组织区，路径绕过模型，不直接进入模型输出端。第六格放大“下一次输入”，其中已保留系统提示词、用户需求、工具定义，并新增“调用记录”金色短条。第七格白色工具结果页落入下一次输入，同框清楚展示三条实际内容，绿色规则仍在上方。第八格缩回全景，完整下一次输入沿向右箭头送入同一个语言模型，模型外观与板层数量不变，执行程序停止且文件留在外部。第九格以框内三条结果及右侧模型为视觉中心，短句“结果成为下一次输入”。关键：工具结果先加入输入，再调用模型；禁止结果直接绕过输入变成最终答案。箭头必须清晰，每格仅突出当前有效路径。",
